<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import AppDialog from './AppDialog.vue';
type Publication={id:number;cliente_id:number;razao_social:string;base:string;versao:string;estado:string;criada_em:string;hash_pdf:string};
type Audit={id:number;criado_em:string;publicacao_id:number|null;evento:string;ator_id:number|null;ip:string;resultado:string};
const props=defineProps<{area:'publicacoes'|'acessos';clients:Array<{id:number;razao_social:string}>;bases:Array<{numero_registro:string}>;request:<T>(path:string,method?:string,body?:unknown)=>Promise<T>;download:(path:string)=>Promise<{blob:Blob;type:string}>}>();
const emit=defineEmits<{success:[message:string]}>();
const publications=ref<Publication[]>([]),events=ref<Audit[]>([]),query=ref(''),state=ref(''),loading=ref(false),error=ref(''),creating=ref(false),selected=ref<Publication|null>(null),revoking=ref<Publication|null>(null),confirmed=ref(false),busy=ref(false),formError=ref(''),clientId=ref(''),base=ref(''),checking=ref(false),ready=ref(false),readiness=ref('Selecione uma CCT para verificar a versão.');let alive=true,generation=0,validation=0;
const matches=(text:string)=>text.toLocaleLowerCase('pt-BR').includes(query.value.trim().toLocaleLowerCase('pt-BR'));
const visible=computed(()=>publications.value.filter(item=>(!state.value||item.estado===state.value)&&matches([item.razao_social,item.base,item.versao].join(' '))));
const visibleEvents=computed(()=>events.value.filter(item=>matches([item.evento,item.ator_id,item.ip,item.publicacao_id,item.resultado].join(' '))));
async function load(){const current=++generation;loading.value=true;error.value='';try{if(props.area==='publicacoes'){const data=await props.request<Publication[]>('/api/contexto/publicacoes');if(alive&&current===generation)publications.value=data;}else{const data=await props.request<Audit[]>('/api/contexto/publicacoes/auditoria');if(alive&&current===generation)events.value=data;}}catch(cause){if(alive&&current===generation)error.value=(cause as Error).message;}finally{if(alive&&current===generation)loading.value=false;}}
async function validate(){const current=++validation;ready.value=false;checking.value=false;if(!base.value){readiness.value='Selecione uma CCT para verificar a versão.';return;}checking.value=true;readiness.value='Verificando consolidação…';try{const data=await props.request<{versao:string|null;resultado:null|{pendencias:string[]};desatualizado:boolean}>('/api/contexto/interpretacoes?base='+encodeURIComponent(base.value));if(!alive||current!==validation)return;ready.value=!!data.versao&&!!data.resultado&&!data.desatualizado&&!data.resultado.pendencias.length;readiness.value=ready.value?'Versão revisada disponível. A publicação preservará esta versão.':'Consolide e resolva as pendências antes de publicar.';}catch(cause){if(alive&&current===validation)readiness.value=(cause as Error).message;}finally{if(alive&&current===validation)checking.value=false;}}
function newPublication(){clientId.value='';base.value='';formError.value='';ready.value=false;creating.value=true;}
function closeCreate(){validation++;creating.value=false;ready.value=false;}
async function publish(){if(busy.value||checking.value||!ready.value||!clientId.value)return;busy.value=true;formError.value='';const current=generation;try{await props.request('/api/contexto/publicacoes','POST',{cliente_id:Number(clientId.value),base:base.value});if(!alive||current!==generation)return;closeCreate();emit('success','Documento publicado.');await load();}catch(cause){if(alive&&current===generation){formError.value=(cause as Error).message;void validate();}}finally{busy.value=false;}}
async function revoke(){if(busy.value||!confirmed.value||!revoking.value)return;busy.value=true;formError.value='';const current=generation;try{await props.request('/api/contexto/publicacoes/'+revoking.value.id+'/revogar','POST',{});if(!alive||current!==generation)return;revoking.value=null;emit('success','Publicação revogada.');await load();}catch(cause){if(alive&&current===generation)formError.value=(cause as Error).message;}finally{busy.value=false;}}
async function csv(){if(busy.value)return;busy.value=true;error.value='';const current=generation;try{const file=await props.download('/api/contexto/publicacoes/auditoria?formato=csv');if(!alive||current!==generation)return;const url=URL.createObjectURL(file.blob),link=document.createElement('a');link.href=url;link.download='auditoria-publicacoes.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(cause){if(alive&&current===generation)error.value=(cause as Error).message;}finally{busy.value=false;}}
watch(()=>props.area,()=>{query.value='';state.value='';closeCreate();selected.value=null;revoking.value=null;void load();},{immediate:true});watch(base,()=>{void validate();});onBeforeUnmount(()=>{alive=false;generation++;validation++;});
</script>
<template><header class="document-panel-heading"><div><h3>{{ area==='publicacoes'?'Publicações para clientes':'Acessos e ciência' }}</h3><p>{{ area==='publicacoes'?'Disponibilize uma versão revisada no portal da empresa.':'Confira eventos registrados com a identidade do usuário e o IP do acesso.' }}</p></div><button v-if="area==='publicacoes'" class="secondary" type="button" @click="newPublication">Nova publicação</button><button v-else class="secondary" type="button" :disabled="busy" @click="csv">Baixar auditoria CSV</button></header>
<div class="registry-controls"><label>{{ area==='publicacoes'?'Buscar publicação':'Buscar evento, usuário ou IP' }}<input v-model="query" type="search"></label><label v-if="area==='publicacoes'">Situação<select v-model="state"><option value="">Todas</option><option value="ativa">Ativas</option><option value="revogada">Revogadas</option></select></label><button class="secondary" type="button" :disabled="loading||busy" @click="load">Atualizar lista</button></div><p v-if="loading" role="status">Carregando…</p><p v-if="error" role="alert">{{ error }}</p>
<div v-if="!loading&&!error" class="registry-scroll"><table v-if="area==='publicacoes'"><caption>Publicações do escritório</caption><thead><tr><th scope="col">Cliente</th><th scope="col">CCT</th><th scope="col">Situação</th><th scope="col">Versão</th><th scope="col">Ações</th></tr></thead><tbody><tr v-for="item in visible" :key="item.id"><td>{{ item.razao_social }}</td><td>{{ item.base }}</td><td>{{ item.estado==='ativa'?'Ativa':'Revogada' }}</td><td>{{ item.versao.slice(0,12) }}</td><td class="contact-row-actions"><button class="secondary" type="button" :aria-label="'Ver publicação '+item.id" @click="selected=item">Ver publicação</button><button v-if="item.estado==='ativa'" class="secondary" type="button" :aria-label="'Revogar publicação '+item.id" @click="revoking=item;confirmed=false;formError=''">Revogar</button></td></tr><tr v-if="!visible.length"><td colspan="5">{{ publications.length?'Nenhum resultado para esta busca.':'Ainda não há publicações neste escritório.' }}</td></tr></tbody></table><table v-else><caption>Auditoria de publicações</caption><thead><tr><th v-for="label in ['Data e hora','Publicação','Evento','Usuário','IP','Resultado']" :key="label" scope="col">{{ label }}</th></tr></thead><tbody><tr v-for="(item,index) in visibleEvents" :key="item.id??index"><td>{{ new Date(item.criado_em).toLocaleString('pt-BR') }}</td><td>{{ item.publicacao_id??'Não identificada' }}</td><td>{{ item.evento }}</td><td>{{ item.ator_id??'Não identificado' }}</td><td>{{ item.ip||'Não informado' }}</td><td>{{ item.resultado }}</td></tr><tr v-if="!visibleEvents.length"><td colspan="6">{{ events.length?'Nenhum resultado para esta busca.':'Nenhum acesso registrado neste escritório.' }}</td></tr></tbody></table></div>
<AppDialog v-if="creating" title="Disponibilizar documento" :busy="busy" @close="closeCreate"><p>A publicação libera acesso no portal do cliente e pode enfileirar notificações conforme as regras do escritório.</p><form class="vue-form" @submit.prevent="publish"><label>Cliente<select v-model="clientId" required><option value="">Selecione</option><option v-for="client in clients" :key="client.id" :value="String(client.id)">{{ client.razao_social }}</option></select></label><label>CCT base consolidada<select v-model="base" required><option value="">Selecione</option><option v-for="item in bases" :key="item.numero_registro">{{ item.numero_registro }}</option></select></label><p role="status">{{ readiness }}</p><p v-if="formError" role="alert">{{ formError }}</p><footer><button class="secondary" type="button" :disabled="busy" @click="closeCreate">Cancelar</button><button class="secondary" type="submit" :disabled="busy||checking||!ready||!clientId">Publicar versão atual</button></footer></form></AppDialog>
<AppDialog v-if="selected" title="Detalhes da publicação" @close="selected=null"><h3>{{ selected.base }}</h3><p>{{ selected.razao_social }}</p><div class="document-info-grid"><article><small>Situação</small><p>{{ selected.estado==='ativa'?'Ativa':'Revogada' }}</p></article><article><small>Publicada em</small><p>{{ new Date(selected.criada_em).toLocaleString('pt-BR') }}</p></article></div><p>Novas revisões não alteram a versão já disponibilizada.</p><details><summary>Identificação da versão</summary><p class="publication-version">{{ selected.versao }}</p><p class="publication-version">SHA-256: {{ selected.hash_pdf }}</p></details></AppDialog>
<AppDialog v-if="revoking" title="Revogar publicação" :busy="busy" @close="revoking=null"><p>Revogar {{ revoking.base }} para {{ revoking.razao_social }}? A empresa perderá o acesso a esta publicação.</p><form class="vue-form" @submit.prevent="revoke"><label class="confirmation-check"><input v-model="confirmed" type="checkbox" required>Confirmo esta ação.</label><p v-if="formError" role="alert">{{ formError }}</p><footer><button class="secondary" type="button" :disabled="busy" autofocus @click="revoking=null">Cancelar</button><button class="secondary" type="submit" :disabled="busy||!confirmed">Revogar publicação</button></footer></form></AppDialog></template>
